<template>
  <div class="page plugin-page">
    <header class="page-heading">
      <div><span class="eyebrow">PLUGIN CONTROL PLANE</span><h1>{{ overview?.release.name || '插件详情' }}</h1><p>查看插件发布、组件、Quickstart、Worker 健康状态与真实执行链路。</p></div>
      <div class="heading-actions"><button v-if="publishableRelease" class="primary-button" :disabled="publishing" @click="publishRelease">{{ publishing ? '提交中…' : `发布 v${publishableRelease.version} 并等待 Worker 确认` }}</button><button class="secondary-button" :disabled="loading" @click="load">{{ loading ? '刷新中…' : '刷新' }}</button></div>
    </header>
    <div v-if="error" class="notice error-notice">{{ error }}</div>
    <template v-else-if="overview">
      <section class="release-strip panel"><div><span class="eyebrow">{{ overview.release.status.toUpperCase() }} RELEASE</span><strong>{{ overview.release.name }}</strong><small>{{ overview.release.plugin_id }} · v{{ overview.release.version }} · {{ overview.release.status }}</small></div><div><span>组件</span><strong>{{ overview.components.length }}</strong></div><div><span>健康 Worker</span><strong>{{ overview.worker_summary.healthy_loaded }}/{{ overview.worker_summary.total }}</strong></div><div><span>24h 成功率</span><strong>{{ percent(overview.metrics.success_rate) }}</strong></div><div><span>P95</span><strong>{{ latency(overview.metrics.p95_duration_ms) }}</strong></div></section>
      <div v-if="pendingReleases.length" class="notice"><strong>待处理发布：</strong><span v-for="item in pendingReleases" :key="item.version">v{{ item.version }} · {{ item.status }} · {{ item.build_digest }}</span><small>staged 版本已进入 rollout；请到平台治理查看 Worker 加载确认、批准、失败原因或安全回滚。</small></div>
      <nav class="plugin-tabs"><button v-for="item in tabs" :key="item.id" :class="{ active: tab === item.id }" @click="tab = item.id">{{ item.label }} <small>{{ item.count }}</small></button></nav>
      <section v-if="tab === 'overview'" class="plugin-grid">
        <article class="panel"><span class="eyebrow">RELEASE</span><h2>{{ overview.release.description }}</h2><dl><dt>Distribution</dt><dd>{{ overview.release.distribution_name || '—' }}</dd><dt>Build</dt><dd>{{ overview.release.build_digest || '未声明' }}</dd></dl></article>
        <article class="panel"><span class="eyebrow">DEPENDENCIES</span><div class="dependency-list"><div v-for="item in dependencies" :key="String(item.id)"><i /> <strong>{{ item.name }}</strong><small>{{ item.kind }} · {{ item.required ? 'required' : 'optional' }}</small></div></div></article>
        <article class="panel wide"><span class="eyebrow">COMPONENT METRICS</span><div class="metric-table"><div v-for="item in overview.metrics.by_component" :key="item.capability_id"><code>{{ item.capability_id }}</code><span>{{ item.total }} calls</span><span>{{ item.failed }} failed</span><span>P95 {{ latency(item.p95_duration_ms) }}</span></div><p v-if="!overview.metrics.by_component.length" class="muted">暂无插件调用记录。</p></div></article>
      </section>
      <section v-else-if="tab === 'quickstart'" class="quickstart-grid">
        <article v-for="item in quickStarts" :key="item.quickstart_id" class="panel quickstart-card">
          <span class="eyebrow">{{ item.scenario_id || 'PLUGIN QUICKSTART' }}</span><h2>{{ item.title }}</h2><p>{{ item.description }}</p>
          <code>{{ item.prompt }}</code>
          <div><span v-for="capability in item.capability_ids" :key="capability">{{ capability }}</span></div>
          <small>{{ item.expected_outcome || '将进入与真实用户完全一致的场景识别、追问、Tool 调用和 Run 观测链路。' }}</small>
          <button class="primary-button" @click="openQuickStart(item)">在 Agent 试用中打开 →</button>
        </article>
      </section>
      <section v-else-if="tab === 'playground'" class="playground-grid">
        <article class="panel playground-editor">
          <span class="eyebrow">COMPONENT PLAYGROUND</span><h2>单组件测试</h2>
          <p>选择任意已发布插件组件进行独立验证。Tool 创建可回放的直接 Run；Scenario 只模拟路由与追问；Skill 校验固定版本和 Worker 将读取的有效策略。</p>
          <label class="config-field"><span>组件</span><select v-model="playgroundComponentId"><option v-for="item in overview.components" :key="item.component_id" :value="item.component_id">{{ item.component_type.toUpperCase() }} · {{ item.name }} · {{ item.reference_id }} v{{ item.reference_version }}</option></select></label>
          <template v-if="playgroundComponent">
            <p class="component-summary"><strong>{{ playgroundComponent.name }}</strong><code>{{ playgroundComponent.reference_id }} · v{{ playgroundComponent.reference_version }}</code></p>
            <p class="settings-note">{{ playgroundComponent.description || '无额外说明' }}</p>
            <template v-if="playgroundComponent.component_type === 'tool' || playgroundComponent.component_type === 'connector'">
              <label class="config-field"><span>输入 JSON</span><textarea v-model="playgroundInput" rows="18" spellcheck="false" /></label>
              <details class="playground-schema"><summary>查看输入 Schema</summary><pre>{{ pretty(playgroundComponent.metadata.input_schema || {}) }}</pre></details>
              <p class="settings-note">直接执行不会经过协调 Agent 或模型规划；仅允许只读、已启用的 Tool / Connector。每次测试都会保留 Run、调用记录和 Artifact。</p>
              <div class="settings-actions"><button class="secondary-button" :disabled="playgroundRunning" @click="resetPlayground">恢复示例</button><button class="primary-button" :disabled="playgroundRunning" @click="runPlayground">{{ playgroundRunning ? '提交中…' : '直接执行 Tool' }}</button></div>
            </template>
            <template v-else-if="playgroundComponent.component_type === 'scenario'">
              <label class="config-field"><span>模拟用户请求</span><textarea v-model="scenarioPrompt" rows="4" spellcheck="false" /></label>
              <label class="config-field"><span>已提供字段 JSON</span><textarea v-model="scenarioInputsText" rows="11" spellcheck="false" /></label>
              <p class="settings-note">模拟不会请求模型、不会创建 Run，也不会触发外部 Tool；它会展示该场景是否命中、需要追问什么、以及允许使用哪些能力。</p>
              <div class="settings-actions"><button class="secondary-button" :disabled="scenarioSimulating" @click="resetPlayground">恢复示例</button><button class="primary-button" :disabled="scenarioSimulating" @click="simulatePlaygroundScenario">{{ scenarioSimulating ? '模拟中…' : '模拟路由与追问' }}</button></div>
            </template>
            <template v-else-if="playgroundComponent.component_type === 'skill'">
              <p class="settings-note">Skill 是固定版本的提示词与策略，不应绕过 Agent 被单独“执行”。此处会读取其已发布版本对应的有效运行时策略，确认配置、启用状态及 Worker 可加载条件；实际行为可通过绑定它的 Agent / Scenario 进行端到端试跑。</p>
              <div class="settings-actions"><button class="secondary-button" :disabled="skillChecking" @click="resetPlayground">清空校验</button><button class="primary-button" :disabled="skillChecking" @click="checkPlaygroundSkill">{{ skillChecking ? '校验中…' : '校验 Skill 策略' }}</button></div>
            </template>
          </template>
        </article>
        <article class="panel playground-result">
          <span class="eyebrow">{{ playgroundResultLabel }}</span><h2>{{ playgroundResultTitle }}</h2>
          <template v-if="playgroundComponent?.component_type === 'tool' || playgroundComponent?.component_type === 'connector'">
            <p v-if="!playgroundRun" class="muted">提交后将在此显示 Run 状态和输出 Artifact。完整时序、输入和调用记录仍可在运行中心查看。</p>
            <template v-else>
            <dl><dt>Run</dt><dd><code>{{ playgroundRun.run_id }}</code></dd><dt>状态</dt><dd>{{ playgroundRun.status }}</dd></dl>
            <div class="result-actions"><button class="secondary-button" :disabled="playgroundRefreshing" @click="refreshPlayground">{{ playgroundRefreshing ? '刷新中…' : '刷新结果' }}</button><button class="primary-button" @click="openRun(playgroundRun!.run_id)">查看完整 Run →</button></div>
            <pre v-if="playgroundArtifact">{{ pretty(playgroundArtifact.content) }}</pre>
            <p v-else class="muted">Worker 完成后点击“刷新结果”读取该 Tool 输出 Artifact。</p>
            </template>
          </template>
          <template v-else-if="playgroundComponent?.component_type === 'scenario'">
            <p v-if="!scenarioResult" class="muted">运行模拟后将显示路由决策、需要追问的字段和能力边界。</p><pre v-else>{{ pretty(scenarioResult) }}</pre>
          </template>
          <template v-else-if="playgroundComponent?.component_type === 'skill'">
            <p v-if="!skillResult" class="muted">校验会读取 Skill 的有效运行时策略；Skill 的不可变正文仍由已发布版本管理。</p>
            <template v-else><dl><dt>能力</dt><dd><code>{{ skillResult.capability_id }}</code></dd><dt>启用状态</dt><dd>{{ skillResult.enabled ? 'enabled' : 'disabled' }}</dd><dt>配置更新时间</dt><dd>{{ skillResult.updated_at || '—' }}</dd></dl><details class="playground-schema" open><summary>有效运行时策略</summary><pre>{{ pretty(skillResult.configuration) }}</pre></details></template>
          </template>
          <p v-else class="muted">从左侧下拉选择一个组件开始测试。</p>
        </article>
      </section>
      <section v-else-if="tab === 'components'" class="components-workspace" :class="{ 'has-settings': selectedComponent && settings }">
        <div class="component-grid"><article v-for="item in overview.components" :key="item.component_id" class="panel component-card" :class="{ selected: selectedComponent?.component_id === item.component_id }"><span class="kind">{{ item.component_type }}</span><h2>{{ item.name }}</h2><code>{{ item.reference_id }} · v{{ item.reference_version }}</code><p>{{ item.description || '无额外说明' }}</p><small v-if="item.metadata.adapter">{{ item.metadata.adapter }}</small><div class="component-actions"><button class="primary-button" @click="openComponentPlayground(item)">{{ item.component_type === 'scenario' ? '模拟测试' : item.component_type === 'skill' ? '校验策略' : '打开 Playground' }}</button><button v-if="configurable(item)" class="secondary-button" @click="openSettings(item)">配置与启停</button><button v-else-if="item.component_type === 'scenario'" class="secondary-button" @click="openScenario(item)">编辑场景</button></div></article></div>
        <aside v-if="selectedComponent && settings" class="panel settings-panel"><div class="settings-heading"><div><span class="eyebrow">RUNTIME SETTINGS</span><h2>{{ selectedComponent.name }}</h2><small>{{ selectedComponent.reference_id }} · 所有 Worker 将在下一次调用读取此配置</small></div><button class="secondary-button" @click="closeSettings">关闭</button></div><label class="switch-row"><input v-model="settings.enabled" type="checkbox" /><span><strong>启用组件</strong><small>关闭后 Agent 不再获得此能力，新的调用会被拒绝。</small></span></label><label class="config-field"><span>运行时配置（JSON）</span><textarea v-model="settingsText" rows="13" spellcheck="false" /></label><details><summary>配置 Schema</summary><pre>{{ pretty(settings.configuration_schema) }}</pre></details><p class="settings-note">只可配置非敏感运行参数。API Key、Token、密码必须留在服务器密钥环境中。</p><div class="settings-actions"><button class="secondary-button" :disabled="settingsSaving" @click="resetSettings">恢复</button><button class="primary-button" :disabled="settingsSaving" @click="saveSettings">{{ settingsSaving ? '保存中…' : '保存并热加载' }}</button></div></aside>
      </section>
      <section v-else-if="tab === 'topology'" class="panel topology"><span class="eyebrow">EXECUTION RELATIONSHIPS</span><div v-if="topology" class="topology-list"><article v-for="node in topology.nodes" :key="node.id"><strong>{{ node.label }}</strong><small>{{ node.kind }}</small><p>{{ links(node.id).join(' · ') || '无下游关联' }}</p></article></div><p v-else class="muted">正在读取关联图…</p></section>
      <section v-else-if="tab === 'health'" class="health-grid"><article v-for="item in health?.checks" :key="item.name" class="panel"><span :class="['status-dot', item.status]" /><span class="eyebrow">{{ item.name }}</span><h2>{{ item.status }}</h2><p>{{ item.summary }}</p></article></section>
      <section v-else class="panel invocation-list"><span class="eyebrow">RECENT INVOCATIONS</span><article v-for="item in invocations" :key="item.invocation_id"><div><code>{{ item.capability_id }}</code><small>{{ item.invocation_id }} · {{ formatDate(item.created_at) }}</small></div><span :class="['status-badge', item.status]">{{ item.status }}</span><button class="secondary-button" @click="openRun(item.run_id)">查看 Run</button></article><p v-if="!invocations.length" class="muted">暂无调用记录。</p></section>
    </template>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { createPluginPlaygroundRun, getPlugin, getPluginHealth, getPluginInvocations, getPluginTopology, publishPluginRelease, type PluginComponent, type PluginHealth, type PluginInvocation, type PluginOverview, type PluginQuickstart, type PluginTopology } from '../api/plugins'
import { getCapabilityRuntimeSettings, saveCapabilityRuntimeSettings, type CapabilityRuntimeSettings } from '../api/admin'
import { getRuntimeArtifacts, getRuntimeRun, type RuntimeArtifact, type RuntimeRun } from '../api/runtime'
import { simulateScenario } from '../api/scenarios'

const route = useRoute(); const router = useRouter(); const pluginId = computed(() => String(route.params.pluginId || '')); const loading = ref(false); const error = ref(''); const tab = ref('overview')
const overview = ref<PluginOverview | null>(null); const topology = ref<PluginTopology | null>(null); const health = ref<PluginHealth | null>(null); const invocations = ref<PluginInvocation[]>([])
const publishing = ref(false)
const selectedComponent = ref<PluginComponent | null>(null); const settings = ref<CapabilityRuntimeSettings | null>(null); const settingsText = ref('{}'); const savedSettingsText = ref('{}'); const settingsSaving = ref(false)
const playgroundComponentId = ref(''); const playgroundInput = ref('{}'); const scenarioPrompt = ref(''); const scenarioInputsText = ref('{}')
const playgroundRun = ref<RuntimeRun | null>(null); const playgroundArtifact = ref<RuntimeArtifact | null>(null); const playgroundRunning = ref(false); const playgroundRefreshing = ref(false)
const scenarioResult = ref<Record<string, unknown> | null>(null); const scenarioSimulating = ref(false); const skillResult = ref<CapabilityRuntimeSettings | null>(null); const skillChecking = ref(false)
const quickStarts = computed(() => overview.value?.release.manifest.quickstarts || [])
const pendingReleases = computed(() => (overview.value?.releases || []).filter((item) => item.status !== 'active' && item.status !== 'retired'))
const publishableRelease = computed(() => pendingReleases.value.find((item) => item.status === 'discovered') || null)
const playgroundComponent = computed(() => overview.value?.components.find((item) => item.component_id === playgroundComponentId.value) || null)
const playgroundResultLabel = computed(() => playgroundComponent.value?.component_type === 'scenario' ? 'ROUTING SIMULATION' : playgroundComponent.value?.component_type === 'skill' ? 'SKILL POLICY CHECK' : 'DURABLE TOOL RESULT')
const playgroundResultTitle = computed(() => playgroundComponent.value?.component_type === 'scenario' ? '模拟结果' : playgroundComponent.value?.component_type === 'skill' ? '策略校验结果' : '执行结果')
const tabs = computed(() => [{ id: 'overview', label: '概览', count: '' }, { id: 'quickstart', label: '试跑示例', count: quickStarts.value.length }, { id: 'playground', label: '组件试验', count: overview.value?.components.length || 0 }, { id: 'components', label: '组件', count: overview.value?.components.length || 0 }, { id: 'topology', label: '关联图', count: topology.value?.edges.length || 0 }, { id: 'health', label: '健康', count: health.value?.checks.length || 0 }, { id: 'invocations', label: '调用', count: invocations.value.length }])
const dependencies = computed(() => overview.value?.release.manifest.dependencies || [])
function percent(value: number) { return `${Math.round(value * 100)}%` }; function latency(value: number | null) { return value == null ? '—' : `${Math.round(value)} ms` }; function formatDate(value: string) { return new Date(value).toLocaleString('zh-CN') }
function pretty(value: unknown) { return JSON.stringify(value || {}, null, 2) }; function configurable(item: PluginComponent) { return item.component_type === 'tool' || item.component_type === 'skill' }
function links(id: string) { return (topology.value?.edges || []).filter((item) => item.source === id).map((item) => topology.value?.nodes.find((node) => node.id === item.target)?.label || item.target) }
async function load() { if (!pluginId.value) return; loading.value = true; error.value = ''; overview.value = null; try { const [item, graph, checks, recent] = await Promise.all([getPlugin(pluginId.value), getPluginTopology(pluginId.value), getPluginHealth(pluginId.value), getPluginInvocations(pluginId.value)]); overview.value = item; topology.value = graph; health.value = checks; invocations.value = recent.items; if (item.components.length) selectPlaygroundComponent(item.components[0]) } catch (cause) { error.value = cause instanceof Error ? cause.message : '读取插件状态失败' } finally { loading.value = false } }
async function publishRelease() { if (!publishableRelease.value) return; publishing.value = true; error.value = ''; try { await publishPluginRelease(pluginId.value, publishableRelease.value.version); await load() } catch (cause) { error.value = cause instanceof Error ? cause.message : '插件发布失败' } finally { publishing.value = false } }
async function openSettings(item: PluginComponent) { selectedComponent.value = item; settings.value = null; error.value = ''; try { const value = await getCapabilityRuntimeSettings(item.reference_id); settings.value = value; settingsText.value = pretty(value.configuration); savedSettingsText.value = settingsText.value } catch (cause) { error.value = cause instanceof Error ? cause.message : '读取组件配置失败' } }
function closeSettings() { selectedComponent.value = null; settings.value = null; settingsText.value = '{}' }; function resetSettings() { settingsText.value = savedSettingsText.value }
async function saveSettings() { if (!selectedComponent.value || !settings.value) return; let configuration: Record<string, unknown>; try { const parsed = JSON.parse(settingsText.value); if (!parsed || Array.isArray(parsed) || typeof parsed !== 'object') throw new Error('配置必须是 JSON 对象'); configuration = parsed as Record<string, unknown> } catch (cause) { error.value = cause instanceof Error ? cause.message : '配置 JSON 无效'; return } settingsSaving.value = true; error.value = ''; try { const value = await saveCapabilityRuntimeSettings(selectedComponent.value.reference_id, { enabled: settings.value.enabled, configuration }); settings.value = { ...settings.value, ...value, configuration_schema: settings.value.configuration_schema }; settingsText.value = pretty(value.configuration); savedSettingsText.value = settingsText.value } catch (cause) { error.value = cause instanceof Error ? cause.message : '保存组件配置失败' } finally { settingsSaving.value = false } }
function openRun(runId: string) { void router.push(`/runs/${encodeURIComponent(runId)}`) }
function playgroundSample(item: PluginComponent | null) { if (!item) return {}; const exampleInput = item.metadata.example_input; const examplePrompt = item.metadata.example_prompt; return { input: exampleInput && typeof exampleInput === 'object' ? pretty(exampleInput) : '{}', prompt: typeof examplePrompt === 'string' ? examplePrompt : undefined } }
function resetPlayground() { const sample = playgroundSample(playgroundComponent.value); playgroundInput.value = sample.input || '{}'; scenarioInputsText.value = sample.input || '{}'; scenarioPrompt.value = sample.prompt || `测试 ${playgroundComponent.value?.name || '组件'}`; playgroundArtifact.value = null; playgroundRun.value = null; scenarioResult.value = null; skillResult.value = null }
function selectPlaygroundComponent(item: PluginComponent) { playgroundComponentId.value = item.component_id; resetPlayground() }
function openComponentPlayground(item: PluginComponent) { tab.value = 'playground'; selectPlaygroundComponent(item) }
async function runPlayground() { const item = playgroundComponent.value; if (!item || !pluginId.value) return; let input: Record<string, unknown>; try { const value = JSON.parse(playgroundInput.value); if (!value || Array.isArray(value) || typeof value !== 'object') throw new Error('输入必须是 JSON 对象'); input = value as Record<string, unknown> } catch (cause) { error.value = cause instanceof Error ? cause.message : 'JSON 无效'; return } playgroundRunning.value = true; error.value = ''; playgroundArtifact.value = null; try { playgroundRun.value = await createPluginPlaygroundRun(pluginId.value, { capability_id: item.reference_id, input }); await refreshPlayground() } catch (cause) { error.value = cause instanceof Error ? cause.message : '创建 Tool Playground Run 失败' } finally { playgroundRunning.value = false } }
async function refreshPlayground() { if (!playgroundRun.value) return; playgroundRefreshing.value = true; error.value = ''; try { const [run, artifacts] = await Promise.all([getRuntimeRun(playgroundRun.value.run_id), getRuntimeArtifacts(playgroundRun.value.run_id)]); playgroundRun.value = run; playgroundArtifact.value = artifacts.find((item) => item.name === 'direct-tool-output' || item.name.endsWith('-output')) || null } catch (cause) { error.value = cause instanceof Error ? cause.message : '读取 Playground 结果失败' } finally { playgroundRefreshing.value = false } }
async function simulatePlaygroundScenario() { const item = playgroundComponent.value; if (!item) return; let inputs: Record<string, unknown>; try { const value = JSON.parse(scenarioInputsText.value); if (!value || Array.isArray(value) || typeof value !== 'object') throw new Error('模拟字段必须是 JSON 对象'); inputs = value as Record<string, unknown> } catch (cause) { error.value = cause instanceof Error ? cause.message : '模拟字段 JSON 无效'; return } scenarioSimulating.value = true; error.value = ''; scenarioResult.value = null; try { scenarioResult.value = await simulateScenario(item.reference_id, Number(item.reference_version), scenarioPrompt.value, inputs) } catch (cause) { error.value = cause instanceof Error ? cause.message : '场景模拟失败' } finally { scenarioSimulating.value = false } }
async function checkPlaygroundSkill() { const item = playgroundComponent.value; if (!item) return; skillChecking.value = true; error.value = ''; skillResult.value = null; try { skillResult.value = await getCapabilityRuntimeSettings(item.reference_id) } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Skill 策略校验失败' } finally { skillChecking.value = false } }
function openScenario(item: PluginComponent) { void router.push({ path: '/scenarios', query: { scenario: item.reference_id, version: item.reference_version } }) }
function openQuickStart(item: PluginQuickstart) { void router.push({ path: '/chat', query: { agent: item.agent_id, prompt: item.prompt, ...(item.scenario_id ? { scenario: item.scenario_id } : {}), ...(item.scenario_inputs ? { scenarioInputs: JSON.stringify(item.scenario_inputs) } : {}), sourcePlugin: pluginId.value } }) }
watch(playgroundComponentId, () => resetPlayground()); watch(pluginId, () => { tab.value = 'overview'; topology.value = null; health.value = null; invocations.value = []; void load() }); onMounted(load)
</script>

